import net.minecraftforge.common.capabilities.CapabilityToken;
import net.minecraftforge.common.capabilities.ICapabilitySerializable;
import net.minecraftforge.common.util.LazyOptional;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public final class ExclusiveSkillStateProvider
implements ICapabilitySerializable<CompoundTag> {
    public static final Capability<ExclusiveSkillState> CAPABILITY = CapabilityManager.get((CapabilityToken)new CapabilityToken<ExclusiveSkillState>(){});
    private final ExclusiveSkillState state = new ExclusiveSkillState();
    private final LazyOptional<ExclusiveSkillState> optional = LazyOptional.of(() -> this.state);

    public static LazyOptional<ExclusiveSkillState> get(Player player) {
        return player.getCapability(CAPABILITY);
    }

    @NotNull
    public <T> LazyOptional<T> getCapability(@NotNull Capability<T> capability, @Nullable Direction side) {
        return capability == CAPABILITY ? this.optional.cast() : LazyOptional.empty();
    }

    public CompoundTag serializeNBT() {
        return this.state.serializeNBT();
    }

    public void deserializeNBT(CompoundTag nbt) {
        this.state.deserializeNBT(nbt);
    }

    public void invalidate() {
        this.optional.invalidate();
    }
}

