import net.minecraftforge.common.capabilities.RegisterCapabilitiesEvent;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid="epicarclib", bus=Mod.EventBusSubscriber.Bus.FORGE)
public final class ExclusiveSkillCapabilityEvents {
    private static final ResourceLocation CAPABILITY_ID = ResourceLocation.fromNamespaceAndPath((String)"epicarclib", (String)"exclusive_skill_state");

    private ExclusiveSkillCapabilityEvents() {
    }

    @SubscribeEvent
    public static void onAttachCapabilities(AttachCapabilitiesEvent<Entity> event) {
        if (event.getObject() instanceof Player) {
            ExclusiveSkillStateProvider provider = new ExclusiveSkillStateProvider();
            event.addCapability(CAPABILITY_ID, (ICapabilityProvider)provider);
            event.addListener(provider::invalidate);
        }
    }

    @SubscribeEvent(priority=EventPriority.HIGHEST)
    public static void onPlayerClone(PlayerEvent.Clone event) {
        Player oldPlayer = event.getOriginal();
        Player newPlayer = event.getEntity();
        oldPlayer.reviveCaps();
        ExclusiveSkillStateProvider.get(oldPlayer).ifPresent(oldState -> ExclusiveSkillStateProvider.get(newPlayer).ifPresent(newState -> newState.copyFrom((ExclusiveSkillState)oldState)));
        oldPlayer.invalidateCaps();
    }

    @Mod.EventBusSubscriber(modid="epicarclib", bus=Mod.EventBusSubscriber.Bus.MOD)
    public static final class ModBusEvents {
        private ModBusEvents() {
        }

        @SubscribeEvent
        public static void onRegisterCapabilities(RegisterCapabilitiesEvent event) {
            event.register(ExclusiveSkillState.class);
        }
    }
}

