import com.dmc.epicarclib.api.exclusive.ExclusiveSkillSnapshot;
import com.dmc.epicarclib.capability.ExclusiveSkillStateProvider;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;
import org.jetbrains.annotations.Nullable;
import yesman.epicfight.skill.Skill;
import yesman.epicfight.skill.SkillSlot;

public final class ExclusiveSkillStateApi {
    private static final Set<ResourceLocation> EXCLUSIVE_SKILLS = ConcurrentHashMap.newKeySet();

    private ExclusiveSkillStateApi() {
    }

    public static void registerExclusiveSkill(@Nullable Skill skill) {
        if (skill != null && skill.getRegistryName() != null) {
            EXCLUSIVE_SKILLS.add(skill.getRegistryName());
        }
    }

    public static boolean isExclusiveSkill(@Nullable ResourceLocation skillId) {
        return skillId != null && EXCLUSIVE_SKILLS.contains(skillId);
    }

    public static boolean importLegacySnapshot(Player player, SkillSlot slot, @Nullable ResourceLocation originalSkill, boolean originalDisabled, @Nullable ResourceLocation replacementSkill, @Nullable ResourceLocation sourceItem) {
        return ExclusiveSkillStateProvider.get(player).resolve().map(state -> {
            ExclusiveSkillSnapshot existing = state.getSnapshot(slot);
            if (existing == null) {
                state.saveSnapshot(slot, new ExclusiveSkillSnapshot(originalSkill, replacementSkill, sourceItem, originalDisabled));
            } else if (ExclusiveSkillStateApi.isExclusiveSkill(existing.originalSkill()) && !ExclusiveSkillStateApi.isExclusiveSkill(originalSkill)) {
                state.saveSnapshot(slot, new ExclusiveSkillSnapshot(originalSkill, existing.replacementSkill() != null ? existing.replacementSkill() : replacementSkill, existing.sourceItem() != null ? existing.sourceItem() : sourceItem, originalDisabled));
            }
            return true;
        }).orElse(false);
    }
}

